import 'dart:convert';
import 'dart:io';
import 'dart:ui' show Locale;

import 'package:flutter_test/flutter_test.dart';
import 'package:ghazal_ui/l10n/generated/gz_localizations.dart';

import 'l10n_calls.g.dart';

/// The generated GzL10n must print the same strings as the web ICU runtime
/// (packages/contracts/fixtures/message-cases.json, generated by tools/export-message-cases.mjs).
void main() {
  final doc = jsonDecode(File('../contracts/fixtures/message-cases.json').readAsStringSync()) as Map<String, Object?>;
  final cases = ((doc['bundles']! as Map<String, Object?>)['ui']! as List<Object?>).cast<Map<String, Object?>>();

  test('the table is present', () => expect(cases.length, greaterThan(200)));

  for (final c in cases) {
    test(c['id']! as String, () {
      final call = kL10nCalls[c['call']];
      expect(call, isNotNull, reason: 'call ${c['call']} is generated');
      expect(call!(lookupGzL10n(Locale(c['lang']! as String))), c['expect']);
    });
  }
}
